// sfx.ts: SFX catalog lookups for the halloween-2022 engines over the ROOT index (video-creation/assets/sfx/library.json,
// generated by sfx_catalog.py build), so a device can name ANY catalog sound: its own set (assets/sfx/halloween-2022/,
// woosh9) or a sound the screenplay pairs with a device that was silent in the source.
// PLACEMENT RULE (overlays.md section 2, the kinetic-text approval): a cue written "ON <frame>" is cut with its attack_sec
// (file start -> loudest sample) ON that frame, so the file starts attack_sec early. A cue the row gives as an explicit
// "file start" offset (woosh9 at +0.133 s) is written as such in the device's sound helper.
import sfxIndex from '../../../../assets/sfx/library.json';
import { HwSoundCue } from './types';

type Row = { id: string; file: string; attack_sec?: number | null; duration_sec?: number | null };
const rows = (sfxIndex as unknown as { index: Row[] }).index;

const row = (id: string): Row => {
  const r = rows.find((x) => x.id === id);
  if (!r) throw new Error(`sound id not in the SFX catalog index (assets/sfx/library.json): ${id}`);
  return r;
};

/** catalog id -> path under video-creation/assets/sfx/ (e.g. 'woosh9' -> 'halloween-2022/woosh9.mp3') */
export const hwSfxPath = (id: string): string => row(id).file;

/** catalog id -> seconds from file start to its loudest sample */
export const hwSfxAttack = (id: string): number => row(id).attack_sec ?? 0;

/** A cue whose ATTACK lands ON the frame at t. */
export const hwOnFrame = (id: string, t: number, note?: string): HwSoundCue => ({ id, at: t - hwSfxAttack(id), note });

/** The screenplay-paired sound of a device that fired NONE in the source: [] when nothing is paired (the source look),
 * else one cue per event time with the sound's attack ON that frame. */
export const hwPaired = (pair: string | undefined, times: number[], note: string): HwSoundCue[] =>
  pair ? times.map((t) => hwOnFrame(pair, t, note)) : [];
